-- Skema mesin pencari. Dijalankan oleh `npm run db:reset` (menghapus semua data).
create extension if not exists unaccent;
create extension if not exists pg_trgm;
create extension if not exists pg_stat_statements;

-- Kamus berbasis berkas (db/tsearch, disalin ke image). Nama tanpa ekstensi.
create text search dictionary idn_sinonim (template = synonym, synonyms = idn_sinonim);
create text search dictionary idn_kata (template = simple, stopwords = idn_stop);
-- Varian pembanding: stemmer Snowball bawaan Postgres untuk Bahasa Indonesia.
create text search dictionary idn_stem_kamus (template = snowball, language = indonesian, stopwords = idn_stop);

-- idn: hapus aksen -> sinonim -> huruf kecil + stopword. Tanpa stemming.
create text search configuration idn (copy = simple);
alter text search configuration idn
  alter mapping for asciiword, word, numword, asciihword, hword, numhword, hword_asciipart, hword_part, hword_numpart
  with unaccent, idn_sinonim, idn_kata;

-- idn_stem: sama, tapi kata akhir di-stem (pembayaran -> bayar).
create text search configuration idn_stem (copy = idn);
alter text search configuration idn_stem
  alter mapping for asciiword, word, asciihword, hword, hword_asciipart, hword_part
  with unaccent, idn_sinonim, idn_stem_kamus;

create table documents (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  title text not null,
  url text not null,
  koleksi text not null default 'bantuan',
  kategori text not null,
  produk text not null,
  updated_at timestamptz not null,
  clicks bigint not null default 0,
  content_hash text not null
);

create table chunks (
  id bigint generated always as identity primary key,
  doc_id bigint not null references documents (id) on delete cascade,
  ord int not null,
  anchor text not null,
  title text not null, -- salinan judul: kolom generated tidak bisa membaca tabel lain
  heading text not null default '',
  body text not null,
  tsv tsvector generated always as (
    setweight(to_tsvector('idn'::regconfig, title), 'A') ||
    setweight(to_tsvector('idn'::regconfig, heading), 'B') ||
    setweight(to_tsvector('idn'::regconfig, body), 'C')
  ) stored,
  -- Judul + subjudul saja: penyaring kandidat untuk kata yang sangat umum (lihat langkah performa).
  tsv_judul tsvector generated always as (
    setweight(to_tsvector('idn'::regconfig, title), 'A') ||
    setweight(to_tsvector('idn'::regconfig, heading), 'B')
  ) stored,
  unique (doc_id, ord)
);

create index chunks_tsv_gin on chunks using gin (tsv);
create index chunks_tsv_judul_gin on chunks using gin (tsv_judul);
create index documents_kategori on documents (kategori);
create index documents_produk on documents (produk);

-- Kosakata untuk "maksud Anda": leksem yang benar-benar ada di indeks.
create materialized view kosakata as
  -- Nama tabel wajib lengkap: Postgres 17+ memakai search_path aman saat membuat/refresh matview.
  select word, ndoc from ts_stat('select tsv from public.chunks')
  where length(word) between 3 and 30 and word !~ '^[0-9]+$';
create unique index kosakata_word on kosakata (word);
create index kosakata_trgm on kosakata using gin (word gin_trgm_ops);

