import { createHash } from "node:crypto";
import { readdir, readFile } from "node:fs/promises";
import { extname, join } from "node:path";
import { marked } from "marked";
import { parse, type HTMLElement } from "node-html-parser";
import postgres from "postgres";

export type Chunk = { anchor: string; heading: string; body: string };
export type Doc = {
  slug: string; title: string; url: string; kategori: string; produk: string;
  updated_at: string; clicks: number; chunks: Chunk[];
};

const MAX_CHUNK = 1500; // karakter; bagian lebih panjang dipecah per paragraf
const DROP = new Set(["script", "style", "nav", "header", "footer", "aside", "noscript", "iframe", "form", "svg"]);

export function slugify(s: string): string {
  return s.normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase()
    .replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60) || "bagian";
}

const clean = (s: string) => s.replace(/\s+/g, " ").trim();

// HTML -> potongan per heading h2/h3. h1 = judul dokumen, bukan bagian.
export function chunkHtml(html: string): { title: string; chunks: Chunk[] } {
  // Default parser menganggap <pre> teks mentah (tag <code> ikut); kita ingin teksnya saja.
  const root = parse(html, { blockTextElements: { script: true, noscript: true, style: true } });
  const title = clean(root.querySelector("h1")?.text ?? root.querySelector("title")?.text ?? "");
  const main = root.querySelector("main") ?? root.querySelector("article") ?? root.querySelector("body") ?? root;
  const sections: { heading: string; anchor: string; parts: string[] }[] = [{ heading: "", anchor: "", parts: [] }];
  let h2 = "";

  const walk = (node: HTMLElement) => {
    for (const n of node.childNodes) {
      if (n.nodeType === 3) { const t = clean(n.text); if (t) sections.at(-1)!.parts.push(t); continue; }
      if (n.nodeType !== 1) continue;
      const el = n as HTMLElement;
      const tag = el.rawTagName.toLowerCase();
      if (DROP.has(tag) || tag === "h1") continue;
      if (tag === "h2" || tag === "h3") {
        const text = clean(el.text);
        if (tag === "h2") h2 = text;
        const heading = tag === "h3" && h2 ? `${h2} › ${text}` : text;
        sections.push({ heading, anchor: el.getAttribute("id") ?? slugify(text), parts: [] });
      } else if (el.querySelector("h2, h3")) {
        walk(el);
      } else {
        const t = clean(el.structuredText);
        if (t) sections.at(-1)!.parts.push(t);
      }
    }
  };
  walk(main);

  const chunks: Chunk[] = [];
  for (const s of sections) {
    let body = "";
    for (const p of s.parts) {
      if (body && body.length + p.length > MAX_CHUNK) {
        chunks.push({ anchor: s.anchor, heading: s.heading, body });
        body = "";
      }
      body = body ? `${body}\n${p}` : p;
    }
    if (body || s.heading) chunks.push({ anchor: s.anchor, heading: s.heading, body });
  }
  return { title, chunks };
}

// Satu berkas .md boleh berisi banyak dokumen; tiap dokumen diawali front matter
// yang baris pertamanya `slug:` (jadi garis `---` biasa di isi artikel tetap aman).
export function parseMarkdown(text: string): Doc[] {
  const docs: Doc[] = [];
  const re = /^---\n(slug:[\s\S]*?)\n---\n([\s\S]*?)(?=^---\nslug:|(?![\s\S]))/gm;
  for (const [, front, md] of text.matchAll(re)) {
    const meta = Object.fromEntries(front.split("\n").map((l) => {
      const i = l.indexOf(":");
      return [l.slice(0, i).trim(), l.slice(i + 1).trim()];
    }));
    const { chunks } = chunkHtml(marked.parse(md, { async: false }));
    docs.push(toDoc(meta, meta.judul, chunks));
  }
  return docs;
}

export function parseHtmlDoc(html: string): Doc {
  const root = parse(html);
  const meta: Record<string, string> = {};
  for (const m of root.querySelectorAll("meta[name]")) meta[m.getAttribute("name")!] = m.getAttribute("content") ?? "";
  const { title, chunks } = chunkHtml(html);
  return toDoc(meta, title, chunks);
}

function toDoc(meta: Record<string, string>, title: string | undefined, chunks: Chunk[]): Doc {
  for (const k of ["slug", "kategori", "produk", "diperbarui"]) {
    if (!meta[k]) throw new Error(`metadata "${k}" kosong pada dokumen "${title ?? "?"}"`);
  }
  if (!title) throw new Error(`judul kosong pada ${meta.slug}`);
  return {
    slug: meta.slug, title, url: `/bantuan/${meta.slug}`,
    kategori: meta.kategori, produk: meta.produk,
    updated_at: new Date(meta.diperbarui).toISOString(),
    clicks: Number(meta.klik ?? 0), chunks,
  };
}

export async function upsert(sql: postgres.Sql, doc: Doc, koleksi = "bantuan"): Promise<boolean> {
  const hash = createHash("sha256").update(JSON.stringify(doc)).digest("hex");
  const [old] = await sql`select content_hash from documents where slug = ${doc.slug}`;
  if (old?.content_hash === hash) return false; // tidak berubah, lewati
  await sql.begin(async (tx) => {
    const [{ id }] = await tx`
      insert into documents (slug, title, url, koleksi, kategori, produk, updated_at, clicks, content_hash)
      values (${doc.slug}, ${doc.title}, ${doc.url}, ${koleksi}, ${doc.kategori}, ${doc.produk},
              ${doc.updated_at}, ${doc.clicks}, ${hash})
      on conflict (slug) do update set title = excluded.title, url = excluded.url,
        kategori = excluded.kategori, produk = excluded.produk, updated_at = excluded.updated_at,
        content_hash = excluded.content_hash
      returning id`;
    await tx`delete from chunks where doc_id = ${id}`;
    const rows = doc.chunks.map((c, ord) => ({ doc_id: id, ord, anchor: c.anchor, title: doc.title, heading: c.heading, body: c.body }));
    if (rows.length) await tx`insert into chunks ${tx(rows)}`;
  });
  return true;
}

if (import.meta.filename === process.argv[1]) {
  const dir = process.argv[2] ?? "korpus";
  const sql = postgres(process.env.DATABASE_URL!, { max: 2 });
  let changed = 0, total = 0;
  for (const f of (await readdir(dir)).sort()) {
    const text = await readFile(join(dir, f), "utf8");
    const docs = extname(f) === ".md" ? parseMarkdown(text) : extname(f) === ".html" ? [parseHtmlDoc(text)] : [];
    for (const d of docs) { total++; if (await upsert(sql, d)) changed++; }
  }
  await sql`refresh materialized view concurrently kosakata`;
  console.log(`${total} dokumen dibaca, ${changed} baru/berubah`);
  await sql.end();
}

import postgres from "postgres";

export const sql = postgres(process.env.DATABASE_URL!, {
  max: Number(process.env.DB_POOL ?? 10),
  onnotice: () => {}, // "query hanya berisi stopword" ditangani sendiri di search.ts
  connection: {
    application_name: "mesin-pencari",
    statement_timeout: Number(process.env.DB_TIMEOUT_MS ?? 2000),
  },
});

import { sql } from "./db.ts";

export type Variant = "dasar" | "cd" | "sinyal" | "cd_sinyal";
export type Kolom = "tsv" | "tsv_stem";
export type Mode = "semua" | "sebagian"; // AND (websearch) atau OR antar-kata
export type Params = {
  q: string; kategori?: string; produk?: string; koleksi?: string; setelah?: string;
  limit?: number; cursor?: string; variant?: Variant; kolom?: Kolom;
};
type Hasil = { dipersempit: boolean; hasil: Record<string, any>[]; berikutnya: string | null };
type Cursor = { s: number; id: string; t: number; q: string; m: Mode; f: boolean }; // f = teks penuh

export class InputError extends Error {}

const VARIAN = (process.env.VARIAN ?? "sinyal") as Variant;
// Kueri yang diperkirakan cocok dengan lebih dari BATAS potongan dianggap "lebar" (0 = matikan).
const BATAS = Number(process.env.BATAS_KATA_UMUM ?? 5_000);

const KONFIG: Record<Kolom, string> = { tsv: "idn", tsv_stem: "idn_stem" };
const MULAI = "\u0002", SELESAI = "\u0003";
const HEADLINE = `StartSel=${MULAI}, StopSel=${SELESAI}, MaxWords=35, MinWords=15, MaxFragments=2, FragmentDelimiter=" … "`;

// ts_headline TIDAK meng-escape HTML. Penanda diganti setelah seluruh teks di-escape.
export const escapeHtml = (s: string) =>
  s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`).replace(/[\u0000-\u0001\u0004-\u0008]/g, "");
export const sorot = (h: string) => escapeHtml(h).replaceAll(MULAI, "<mark>").replaceAll(SELESAI, "</mark>");

const encodeCursor = (c: Cursor) => Buffer.from(JSON.stringify(c)).toString("base64url");
function decodeCursor(raw: string): Cursor {
  try {
    const c = JSON.parse(Buffer.from(raw, "base64url").toString());
    if (typeof c.s === "number" && /^\d+$/.test(c.id) && Number.isFinite(c.t) && typeof c.q === "string"
      && (c.m === "semua" || c.m === "sebagian") && typeof c.f === "boolean") return c;
  } catch {}
  throw new InputError("cursor tidak valid");
}

function tsquery(mode: Mode, cfg: string, q: string) {
  return mode === "semua"
    ? sql`websearch_to_tsquery(${cfg}::regconfig, ${q})`
    : sql`(select coalesce(string_agg(quote_literal(l), ' | '), '')::tsquery
           from unnest(tsvector_to_array(to_tsvector(${cfg}::regconfig, ${q}))) l)`;
}

function skor(v: Variant, kolom: Kolom, asof: Date) {
  const tsv = sql`c.${sql(kolom)}`;
  // ts_rank: frekuensi berbobot. ts_rank_cd: kedekatan antar-kata (cover density), jauh lebih mahal.
  // Normalisasi 1 = bagi dengan 1 + log(panjang potongan), supaya potongan panjang tidak selalu menang.
  const teks = v.startsWith("cd") ? sql`ts_rank_cd(${tsv}, q.q, 1)` : sql`ts_rank(${tsv}, q.q, 1)`;
  if (v === "dasar" || v === "cd") return teks;
  // Sinyal: kesegaran (paruh ~1 tahun, maks 20%) dan klik (logaritmik, supaya tidak mendominasi).
  return sql`${teks}
    * (0.8 + 0.2 * exp(-extract(epoch from (${asof}::timestamptz - d.updated_at)) / 86400 / 365))
    * (1 + 0.1 * ln(1 + d.clicks))`;
}

// Kueri lebar (kata sangat umum) membuat Postgres me-ranking puluhan ribu baris.
// Untuk kueri seperti itu, kandidat disaring dari judul + subjudul saja (tsv_judul), lalu
// tetap di-ranking dengan tsv penuh. Perkiraan lebar diambil dari kosakata (ts_stat), murah.
async function saringan(mode: Mode, q: string, kolom: Kolom): Promise<"tsv" | "tsv_judul" | "tsv_stem"> {
  if (!BATAS || kolom !== "tsv") return kolom;
  // Perkiraan jumlah baris yang harus di-ranking: AND <= kata paling jarang, OR ~ jumlah semua kata.
  const [{ n }] = await sql`
    select ${mode === "semua" ? sql`min(k.ndoc)` : sql`sum(k.ndoc)`}::int as n
    from kosakata k where k.word = any(tsvector_to_array(to_tsvector('idn', ${q})))`;
  return n > BATAS ? "tsv_judul" : "tsv";
}

// Bagian bersama: kueri + filter. Dipakai pencarian dan facet.
async function cocok(p: Params, mode: Mode, q: string, penuh: boolean) {
  const kolom = p.kolom ?? "tsv";
  const saring = penuh ? kolom : await saringan(mode, q, kolom);
  return {
    kolom, dipersempit: saring === "tsv_judul",
    cte: sql`q as (select ${tsquery(mode, KONFIG[kolom], q)} as q)`,
    where: sql`c.${sql(saring)} @@ q.q
      ${p.koleksi ? sql`and d.koleksi = ${p.koleksi}` : sql``}
      ${p.kategori ? sql`and d.kategori = ${p.kategori}` : sql``}
      ${p.produk ? sql`and d.produk = ${p.produk}` : sql``}
      ${p.setelah ? sql`and d.updated_at >= ${p.setelah}::date` : sql``}`,
  };
}

export async function search(p: Params, mode: Mode, q: string, cur: Cursor | null, penuh = false): Promise<Hasil> {
  const limit = p.limit ?? 10;
  const asof = new Date(cur?.t ?? Date.now()); // skor kesegaran dibekukan selama paging
  const { kolom, dipersempit, cte, where } = await cocok(p, mode, q, penuh);
  const rows = await sql`
    with ${cte},
    hits as (
      select distinct on (c.doc_id) c.doc_id, c.id as chunk_id, (${skor(p.variant ?? VARIAN, kolom, asof)})::float8 as skor
      from q, chunks c join documents d on d.id = c.doc_id
      where ${where}
      order by c.doc_id, skor desc, c.ord
    ),
    page as (
      select * from hits
      ${cur ? sql`where (skor, doc_id) < (${cur.s}::float8, ${cur.id}::bigint)` : sql``}
      order by skor desc, doc_id desc
      limit ${limit + 1}
    )
    select p.skor, d.id, d.slug, d.title, d.kategori, d.produk, d.updated_at, c.heading,
      case when c.anchor = '' then d.url else d.url || '#' || c.anchor end as url,
      ts_headline(${KONFIG[kolom]}::regconfig, c.body, q.q, ${HEADLINE}) as cuplikan
    from page p join documents d on d.id = p.doc_id join chunks c on c.id = p.chunk_id, q
    order by p.skor desc, p.doc_id desc`;
  // Disaring dari judul tapi kosong (misalnya karena filter): ulangi dengan teks penuh.
  if (!rows.length && dipersempit && !cur) return search(p, mode, q, cur, true);
  const more = rows.length > limit;
  const hasil = rows.slice(0, limit).map((r) => ({
    id: r.id, slug: r.slug, judul: r.title, bagian: r.heading, url: r.url, kategori: r.kategori,
    produk: r.produk, diperbarui: r.updated_at, skor: r.skor, cuplikan: sorot(r.cuplikan),
  }));
  const last = hasil.at(-1);
  return { dipersempit, hasil, berikutnya: more && last ? encodeCursor({ s: last.skor, id: last.id, t: asof.getTime(), q, m: mode, f: !dipersempit }) : null };
}

export async function facets(p: Params, mode: Mode, q: string, penuh: boolean) {
  const { cte, where } = await cocok(p, mode, q, penuh);
  const [r] = await sql`
    with ${cte},
    hits as (select distinct c.doc_id from q, chunks c join documents d on d.id = c.doc_id where ${where})
    select (select count(*) from hits)::int as total,
      (select coalesce(jsonb_object_agg(kategori, n), '{}') from (select d.kategori, count(*)::int n
         from hits h join documents d on d.id = h.doc_id group by 1) x) as kategori,
      (select coalesce(jsonb_object_agg(produk, n), '{}') from (select d.produk, count(*)::int n
         from hits h join documents d on d.id = h.doc_id group by 1) x) as produk`;
  return r;
}

// "Maksud Anda": ganti kata yang leksemnya tidak ada di kosakata dengan kata terdekat (trigram).
export async function saran(q: string): Promise<string | null> {
  const words = [...new Set(q.toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [])].slice(0, 8);
  if (!words.length) return null;
  const rows = await sql`
    select w, (select k.word from kosakata k where k.word % l.lex
               order by k.word <-> l.lex, k.ndoc desc limit 1) as ganti
    from unnest(${words}::text[]) w,
      lateral (select (tsvector_to_array(to_tsvector('idn', w)))[1] as lex) l
    where length(l.lex) >= 3 and not exists (select 1 from kosakata k where k.word = l.lex)`;
  let out = q;
  for (const r of rows) {
    if (r.ganti) out = out.replace(new RegExp(`(?<![\\p{L}\\p{N}])${r.w}(?![\\p{L}\\p{N}])`, "giu"), r.ganti);
  }
  return out === q ? null : out;
}

// Alur lengkap: AND -> koreksi ejaan -> OR. Halaman berikutnya memakai mode dan kueri di cursor.
export async function cari(p: Params) {
  const cur = p.cursor ? decodeCursor(p.cursor) : null;
  if (cur) return { q: cur.q, koreksi: null, sebagian: cur.m === "sebagian", ...(await search(p, cur.m, cur.q, cur, cur.f)) };

  let q = p.q, mode: Mode = "semua", koreksi: string | null = null;
  let res = await search(p, mode, q, null);
  if (!res.hasil.length) {
    const [{ n }] = await sql`select numnode(websearch_to_tsquery('idn', ${q})) as n`;
    if (n === 0) throw new InputError("kueri hanya berisi kata umum; tambahkan kata kunci");
    const s = await saran(q);
    if (s) {
      const r2 = await search(p, mode, s, null);
      if (r2.hasil.length) { res = r2; q = s; koreksi = s; }
    }
    if (!res.hasil.length) { mode = "sebagian"; res = await search(p, mode, q, null); }
  }
  return { q, koreksi, sebagian: mode === "sebagian", ...res, ...(await facets(p, mode, q, !res.dipersempit)) };
}

import Fastify from "fastify";
import rateLimit from "@fastify/rate-limit";
import client from "prom-client";
import { sql } from "./db.ts";
import { cari, InputError, type Params } from "./search.ts";

const durasi = new client.Histogram({
  name: "pencarian_durasi_detik", help: "Durasi /cari", labelNames: ["cache", "hasil"],
  buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.2, 0.5, 1, 2],
});
client.collectDefaultMetrics();

// Cache LRU sederhana di memori: Map menyimpan urutan sisip, entri tertua dibuang dulu.
// ponytail: cache per proses; pakai Redis atau CDN kalau API lebih dari satu instance.
const TTL = 60_000, MAKS = 500;
const cache = new Map<string, { at: number; body: unknown }>();
function ambil(key: string) {
  const e = cache.get(key);
  if (!e || Date.now() - e.at > TTL) return undefined;
  cache.delete(key); cache.set(key, e); // tandai baru dipakai
  return e.body;
}
function simpan(key: string, body: unknown) {
  cache.set(key, { at: Date.now(), body });
  if (cache.size > MAKS) cache.delete(cache.keys().next().value!);
}

const nama = { type: "string", pattern: "^[a-z0-9-]{1,40}$" };
const cariSchema = {
  querystring: {
    type: "object", additionalProperties: false, required: ["q"],
    properties: {
      q: { type: "string", minLength: 1, maxLength: 200 },
      kategori: nama, produk: nama, koleksi: nama,
      setelah: { type: "string", format: "date" },
      limit: { type: "integer", minimum: 1, maximum: 50, default: 10 },
      cursor: { type: "string", maxLength: 600 },
    },
  },
};

export async function buildApp(opts: { rateMax?: number; logger?: boolean } = {}) {
  const app = Fastify({ logger: opts.logger ?? true, trustProxy: process.env.TRUST_PROXY === "1" });
  await app.register(rateLimit, { max: opts.rateMax ?? Number(process.env.RATE_LIMIT_MAX ?? 60), timeWindow: "1 minute" });

  app.setErrorHandler((err, req, reply) => {
    if (err instanceof InputError) return reply.code(400).send({ error: err.message });
    if ((err as { statusCode?: number }).statusCode! < 500) return reply.send(err);
    req.log.error(err);
    return reply.code(500).send({ error: "terjadi kesalahan" });
  });

  app.get("/cari", { schema: cariSchema }, async (req, reply) => {
    const p = req.query as Params;
    const mulai = performance.now();
    const key = JSON.stringify([p.q.trim().toLowerCase(), p.kategori, p.produk, p.koleksi, p.setelah, p.limit, p.cursor]);
    let body = ambil(key) as Awaited<ReturnType<typeof cari>> | undefined;
    const status = body ? "hit" : "miss";
    if (!body) { body = await cari(p); simpan(key, body); }
    const ms = performance.now() - mulai;
    durasi.observe({ cache: status, hasil: body.hasil.length ? "ada" : "nol" }, ms / 1000);
    req.log.info({ q: p.q, hasil: body.hasil.length, koreksi: body.koreksi, sebagian: body.sebagian, cache: status, ms: Math.round(ms) }, "cari");
    reply.header("x-cache", status).header("cache-control", "public, max-age=60")
      .header("server-timing", `cari;dur=${ms.toFixed(1)}`);
    return body;
  });

  app.post("/klik", {
    schema: { body: { type: "object", required: ["id"], properties: { id: { type: "string", pattern: "^[0-9]{1,18}$" } } } },
  }, async (req, reply) => {
    // ponytail: satu klik = +1 tanpa dedup; tambahkan dedup per sesi kalau ada yang memanipulasi peringkat.
    await sql`update documents set clicks = clicks + 1 where id = ${(req.body as { id: string }).id}`;
    return reply.code(204).send();
  });

  app.get("/sehat", { config: { rateLimit: false } }, async () => {
    await sql`select 1`;
    return { ok: true };
  });

  app.get("/metrics", { config: { rateLimit: false } }, async (_req, reply) =>
    reply.type(client.register.contentType).send(await client.register.metrics()));

  return app;
}

