// Relevan = nilai >= 2 (skala 0-3). nDCG memakai gain bertingkat 2^nilai - 1.
export function precisionAt(k: number, ranked: string[], rel: Record<string, number>) {
  return ranked.slice(0, k).filter((s) => (rel[s] ?? 0) >= 2).length / k;
}
export function reciprocalRank(ranked: string[], rel: Record<string, number>) {
  const i = ranked.findIndex((s) => (rel[s] ?? 0) >= 2);
  return i < 0 ? 0 : 1 / (i + 1);
}
export function ndcgAt(k: number, ranked: string[], rel: Record<string, number>) {
  const dcg = (gains: number[]) => gains.slice(0, k).reduce((a, g, i) => a + (2 ** g - 1) / Math.log2(i + 2), 0);
  const ideal = dcg(Object.values(rel).sort((a, b) => b - a));
  return ideal ? dcg(ranked.map((s) => rel[s] ?? 0)) / ideal : 0;
}

// Evaluasi relevansi: jalankan kueri berlabel, hitung P@5, MRR, dan nDCG@10 per varian.
//   npm run eval                      -> semua varian, hanya koleksi "bantuan"
//   npm run eval -- sinyal stem       -> varian tertentu ("stem" butuh kolom tsv_stem)
//   npm run eval -- --semua           -> termasuk dokumen sintetis sebagai pengecoh
import { readFileSync } from "node:fs";
import { sql } from "../src/db.ts";
import { cari, type Params } from "../src/search.ts";
import { ndcgAt, precisionAt, reciprocalRank } from "./metrik.ts";

type Judged = { q: string; rel: Record<string, number> };
const judged: Judged[] = JSON.parse(readFileSync("eval/judgments.json", "utf8"));

const VARIAN: Record<string, Partial<Params>> = {
  dasar: { variant: "dasar" },
  cd: { variant: "cd" },
  sinyal: { variant: "sinyal" },
  cd_sinyal: { variant: "cd_sinyal" },
  stem: { variant: "sinyal", kolom: "tsv_stem" },
};

// --semua: cari di semua koleksi (termasuk 100k dokumen sintetis sebagai pengecoh, dianggap tidak relevan).
const semua = process.argv.includes("--semua");
const args = process.argv.slice(2).filter((a) => a !== "--semua");
const names = args.length ? args : ["dasar", "cd", "sinyal", "cd_sinyal"];
const rows: Record<string, string | number>[] = [];
const worst: string[] = [];
for (const name of names) {
  const v = VARIAN[name];
  if (!v) throw new Error(`varian tidak dikenal: ${name}`);
  let p5 = 0, mrr = 0, ndcg = 0;
  for (const j of judged) {
    const res = await cari({ q: j.q, koleksi: semua ? undefined : "bantuan", limit: 10, ...v });
    const ranked = res.hasil.map((h) => h.slug);
    const n = ndcgAt(10, ranked, j.rel);
    p5 += precisionAt(5, ranked, j.rel); mrr += reciprocalRank(ranked, j.rel); ndcg += n;
    if (n < 0.5) worst.push(`${name.padEnd(6)} nDCG ${n.toFixed(2)}  "${j.q}" -> ${ranked.slice(0, 3).join(", ") || "(kosong)"}`);
  }
  const N = judged.length;
  rows.push({ varian: name, "P@5": +(p5 / N).toFixed(3), MRR: +(mrr / N).toFixed(3), "nDCG@10": +(ndcg / N).toFixed(3) });
}
console.table(rows);
if (worst.length) console.log("Kueri terlemah (nDCG < 0.5):\n" + worst.join("\n"));
await sql.end();

