//   npm run gen               -> 100000 dokumen
//   npm run gen -- 20000      -> lebih sedikit, untuk mesin kecil
// Memori tetap kecil: baris ditulis ke stream COPY satu per satu dan menunggu 'drain'.
import { once } from "node:events";
import postgres from "postgres";

const N = Number(process.argv[2] ?? 100_000);
const BATCH = 10_000;
const ID0 = 1_000_000; // id sintetis jauh dari id korpus asli
const sql = postgres(process.env.DATABASE_URL!, { max: 1, onnotice: () => {} });

// PRNG deterministik: data sama setiap kali dijalankan, hasil benchmark bisa dibandingkan.
let seed = 42;
const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 2 ** 32);

const KATA = ("pesanan produk toko akun pembayaran pengiriman stok harga kasir pembeli penjual laporan " +
  "voucher diskon kurir resi alamat saldo pencairan rekening faktur pajak langganan aplikasi notifikasi " +
  "printer struk gudang varian kategori foto ulasan rating komplain retur refund promosi iklan kampanye " +
  "integrasi webhook token sinkron impor ekspor jadwal shift karyawan pelanggan member poin hadiah " +
  "ongkos berat dimensi asuransi cicilan tunai transfer qris dompet bank cabang outlet meja menu dapur " +
  "resep bahan pemasok pembelian tagihan jatuh tempo pengingat dasbor grafik target omzet margin").split(" ");
const KERJA = "mengatur membuat mengubah menghapus melihat mengunduh mengirim menyambungkan memeriksa membatalkan".split(" ");
const KATEGORI = ["akun", "keamanan", "pembayaran", "pengiriman", "toko", "kasir", "aplikasi"];
const PRODUK = ["web", "aplikasi", "kasir"];

// Kosakata 20.000 kata semu + kata sungguhan di peringkat 20, 40, 60, ...
// Peringkat diambil log-uniform (frekuensi ~ 1/peringkat, hukum Zipf): beberapa kata sangat umum,
// sebagian besar jarang. Tanpa ini setiap kata muncul di hampir semua dokumen dan hasil benchmark menipu.
const SUKU = "ba be bi bo bu da di du ga gi ka ke ki ku la li lu ma me mi mu na ni nu pa pe pi ra ri ru sa se si su ta te ti tu wa ya".split(" ");
const VOCAB = Array.from({ length: 20_000 }, (_, i) =>
  SUKU[i % 40] + SUKU[Math.floor(i / 40) % 40] + SUKU[Math.floor(i / 1600) % 40]);
KATA.forEach((k, i) => { VOCAB[20 + i * 20] = k; });
const kata = () => VOCAB[Math.floor(VOCAB.length ** rnd()) - 1];
const pick = <T,>(xs: T[]) => xs[Math.floor(rnd() * xs.length)];
const kalimat = (n: number) => Array.from({ length: n }, kata).join(" ");
const tsv = (v: string) => v.replace(/[\\\t\n\r]/g, " "); // aman untuk format teks COPY

async function copyRows(stmt: postgres.PendingQuery<postgres.Row[]>, rows: Iterable<string[]>) {
  const stream = await stmt.writable();
  for (const r of rows) {
    if (!stream.write(r.map(tsv).join("\t") + "\n")) await once(stream, "drain");
  }
  stream.end();
  await once(stream, "finish");
}

