// Uji beban kecil: kirim campuran kueri ke API dan laporkan p50/p95/p99.
//   npm run bench -- http://localhost:3000 400 4 1   (url, jumlah request, konkurensi, seed)
// Seed berbeda = kueri berbeda: pakai seed 1 untuk pemanasan, seed lain untuk pengukuran.
const [base = "http://localhost:3000", total = "400", conc = "4", seedArg = "1"] = process.argv.slice(2);

const KATA = ["pesanan", "produk", "stok", "pembayaran", "kurir", "resi", "voucher", "printer", "struk",
  "refund", "faktur", "notifikasi", "qris", "gudang", "laporan", "omzet", "pajak", "cicilan", "webhook",
  "integrasi", "pemasok", "asuransi", "shift", "membatalkan", "menghapus", "pengiriman", "rekening"];
let seed = Number(seedArg);
const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 2 ** 32);
const pick = () => KATA[Math.floor(rnd() * KATA.length)];

// 70% kueri 1-2 kata, 20% 3 kata, 10% salah ketik; 30% memakai filter kategori.
function kueri() {
  const r = rnd();
  let q = r < 0.7 ? [pick(), pick()].slice(0, 1 + Math.floor(rnd() * 2)).join(" ")
    : r < 0.9 ? `${pick()} ${pick()} ${pick()}` : pick().replace(/[aeiou]/, "");
  const p = new URLSearchParams({ q });
  if (rnd() < 0.3) p.set("kategori", ["akun", "pembayaran", "pengiriman", "kasir"][Math.floor(rnd() * 4)]);
  return p;
}

